package at.hausgarten.service;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;

/** Transactional browser-media graph ownership. Bytes remain immutable private files. */
final class BrowserMediaRepositoryRules {
    static final String PREFIX="browser_media:v1:";
    interface Work {JSONObject run()throws Exception;}
    interface Store {
        JSONObject identity()throws Exception;
        String get(String key,String fallback)throws Exception;
        void put(String key,String value)throws Exception;
        void remove(String key)throws Exception;
        JSONArray entries(String prefix)throws Exception;
        JSONObject transaction(Work work)throws Exception;
    }
    private final Store store;private final File media;private final JSONObject bound;
    BrowserMediaRepositoryRules(Store store,File media)throws Exception {this.store=store;this.media=media;bound=identity(store.identity());}
    private static IOException fail(String code){return new IOException("BROWSER_MEDIA_"+code);}
    private static JSONObject copy(JSONObject value)throws Exception{return new JSONObject(value.toString());}
    private static String hash(Object value)throws Exception{return PixelMcpWriteTools.hash(value);}
    private static String stamp(){return Instant.now().toString();}
    private static JSONObject identity(JSONObject raw)throws Exception {String installation=raw.optString("installationId"),epoch=raw.optString("restoreEpoch");if(installation.isEmpty()||epoch.isEmpty()||installation.length()>200||epoch.length()>200)throw fail("CONTEXT_INVALID");return new JSONObject().put("installation_id",installation).put("restore_epoch",epoch);}
    private static void version(JSONObject value)throws Exception {Object v=value.opt("formatVersion");if(!(v instanceof Number)||!v.toString().equals("1"))throw fail("VERSION_UNSUPPORTED");}
    private void context()throws Exception {if(!hash(bound).equals(hash(identity(store.identity()))))throw fail("CONTEXT_CHANGED");}
    private boolean matches(JSONObject value){return value.optString("installation_id").equals(bound.optString("installation_id"))&&value.optString("restore_epoch").equals(bound.optString("restore_epoch"));}
    private JSONObject fresh()throws Exception {return copy(bound).put("formatVersion",1).put("mode","MIRROR_REQUIRED").put("mirror_complete",false).put("device_mirror_complete",false);}
    private JSONObject state()throws Exception {context();String raw=store.get(PREFIX+"state","");JSONObject state=raw.isEmpty()?fresh():new JSONObject(raw);version(state);if(!matches(state))throw fail("CONTEXT_CHANGED");if(!Arrays.asList("MIRROR_REQUIRED","ACTIVE","RESTORE_REVIEW").contains(state.optString("mode")))throw fail("STATE_INVALID");return state;}
    private void saveState(JSONObject state)throws Exception {store.put(PREFIX+"state",state.toString());}
    private static String key(String key)throws Exception {if(key==null||key.length()>500||!(key.equals("selected")||key.startsWith("customer-draft:")&&key.length()>15)||key.matches("(?s).*[\\p{Cntrl}].*"))throw fail("KEY_INVALID");return key;}
    private static String request(String request)throws Exception {if(request==null||!request.matches("[A-Za-z0-9_.:-]{8,200}"))throw fail("REQUEST_ID_REQUIRED");return request;}
    private JSONObject mutate(String operation,String request,JSONObject args,Work work)throws Exception {
        request(request);return store.transaction(()->{state();String receiptKey=PREFIX+"request:"+hash(request),fingerprint=hash(new JSONObject().put("operation",operation).put("args",args).put("context",bound));String raw=store.get(receiptKey,"");if(!raw.isEmpty()){JSONObject receipt=new JSONObject(raw);version(receipt);if(!matches(receipt))throw fail("CONTEXT_CHANGED");if(!fingerprint.equals(receipt.optString("fingerprint")))throw fail("REPLAY_MISMATCH");return copy(receipt.getJSONObject("result")).put("replayed",true);}JSONObject result=work.run().put("formatVersion",1).put("installation_id",bound.getString("installation_id")).put("restore_epoch",bound.getString("restore_epoch")).put("replayed",false);JSONObject receipt=copy(bound).put("formatVersion",1).put("fingerprint",fingerprint).put("result",result);store.put(receiptKey,receipt.toString());return result;});
    }
    JSONObject status()throws Exception {JSONObject state=state();return copy(bound).put("formatVersion",1).put("mode",state.getString("mode")).put("mirror_complete",complete(state));}
    private static boolean complete(JSONObject state){return state.optString("mode").equals("ACTIVE")?state.optBoolean("mirror_complete"):state.optString("mode").equals("RESTORE_REVIEW")&&state.optBoolean("device_mirror_complete");}
    private JSONArray rows(String prefix)throws Exception {return store.entries(PREFIX+prefix);}
    private static JSONObject value(JSONObject entry)throws Exception {JSONObject value=entry.getJSONObject("value");version(value);return value;}
    private JSONObject record(String id)throws Exception {if(id==null||!id.matches("[0-9a-f]{64}"))throw fail("RECORD_INVALID");String raw=store.get(PREFIX+"record:"+id,"");if(raw.isEmpty())throw fail("RECORD_MISSING");JSONObject record=new JSONObject(raw);version(record);Object graph=record.opt("graph");if(graph==null||!(graph==JSONObject.NULL||graph instanceof JSONObject)||!id.equals(record.optString("record_id"))||!id.equals(hash(graph)))throw fail("RECORD_INVALID");if(graph instanceof JSONObject)BrowserMediaFiles.references((JSONObject)graph);return record;}
    private String storeGraph(JSONObject graph)throws Exception {Object body=graph==null?JSONObject.NULL:graph;if(graph!=null){if(graph.toString().getBytes(StandardCharsets.UTF_8).length>2*1024*1024)throw fail("GRAPH_TOO_LARGE");verify(graph);}String id=hash(body),raw=store.get(PREFIX+"record:"+id,"");if(raw.isEmpty())store.put(PREFIX+"record:"+id,new JSONObject().put("formatVersion",1).put("record_id",id).put("graph",body).toString());else record(id);return id;}
    private void verify(JSONObject graph)throws Exception {JSONArray refs=BrowserMediaFiles.references(graph);for(int i=0;i<refs.length();i++)BrowserMediaFiles.verifyReference(media,refs.getJSONObject(i));}
    private void verifyRecord(String id)throws Exception {Object graph=record(id).get("graph");if(graph instanceof JSONObject)verify((JSONObject)graph);}
    private JSONObject pointer(String key)throws Exception {String raw=store.get(PREFIX+"active:"+hash(key),"");if(raw.isEmpty())return null;JSONObject value=new JSONObject(raw);version(value);if(!key.equals(value.optString("key"))||!matches(value))throw fail("CONTEXT_CHANGED");record(value.getString("record_id"));return value;}
    JSONObject readRecord(String key)throws Exception {key(key);JSONObject state=state();if(!state.getString("mode").equals("ACTIVE")||!complete(state))throw fail(state.getString("mode").equals("RESTORE_REVIEW")?"RESTORE_REVIEW_REQUIRED":"MIRROR_REQUIRED");JSONObject pointer=pointer(key);String id=pointer==null?hash(JSONObject.NULL):pointer.getString("record_id");if(pointer!=null)verifyRecord(id);Object graph=pointer==null?JSONObject.NULL:record(id).get("graph");return copy(bound).put("formatVersion",1).put("key",key).put("record_id",pointer==null?JSONObject.NULL:id).put("record_hash",id).put("record",graph);}
    JSONObject writeRecord(String request,String key,String expected,JSONObject graph)throws Exception {key(key);return mutate("write",request,new JSONObject().put("key",key).put("expected",expected).put("graph_hash",hash(graph==null?JSONObject.NULL:graph)),()->{JSONObject current=readRecord(key);if(expected==null||!expected.equals(current.getString("record_hash")))throw fail("WRITE_CONFLICT");String id=storeGraph(graph);JSONObject pointer=copy(bound).put("formatVersion",1).put("key",key).put("record_id",id);store.put(PREFIX+"active:"+hash(key),pointer.toString());store.put(PREFIX+"history:"+hash(request),copy(pointer).put("before",current.opt("record_id")).put("request_id",request).put("at",stamp()).toString());return new JSONObject().put("key",key).put("record_id",id).put("record_hash",id).put("local_state","local_saved");});}
    private static void source(String source)throws Exception {if(!Arrays.asList("active","device").contains(source))throw fail("SOURCE_INVALID");}
    JSONObject beginMirror(String request,String source)throws Exception {source(source);return mutate("begin_mirror",request,new JSONObject().put("source",source),()->{JSONObject state=state();if(source.equals("active")&&state.getString("mode").equals("ACTIVE"))return status().put("already_complete",true).put("mirror_id",state.optString("active_mirror"));if(source.equals("active")&&!state.getString("mode").equals("MIRROR_REQUIRED")||source.equals("device")&&!state.getString("mode").equals("RESTORE_REVIEW"))throw fail("MIRROR_NOT_ALLOWED");if(source.equals("device")&&state.optBoolean("device_mirror_complete"))return status().put("already_complete",true).put("mirror_id",state.optString("device_mirror"));String field=source+"_mirror",id=state.optString(field);if(id.isEmpty()){id=hash(new JSONObject().put("request",request).put("context",bound).put("source",source));JSONObject session=copy(bound).put("formatVersion",1).put("mirror_id",id).put("source",source).put("phase","OPEN");store.put(PREFIX+"mirror:"+id,session.toString());state.put(field,id);saveState(state);}return status().put("already_complete",false).put("mirror_id",id);});}
    private JSONObject mirror(String source)throws Exception {JSONObject state=state();String id=state.optString(source+"_mirror");String raw=store.get(PREFIX+"mirror:"+id,"");if(id.isEmpty()||raw.isEmpty())throw fail("MIRROR_REQUIRED");JSONObject session=new JSONObject(raw);version(session);if(!matches(session)||!source.equals(session.optString("source"))||!session.optString("phase").equals("OPEN"))throw fail("MIRROR_CLOSED");return session;}
    JSONObject writeMirrorRecord(String request,String source,String key,JSONObject graph)throws Exception {source(source);key(key);if(graph==null)throw fail("GRAPH_INVALID");return mutate("mirror_record",request,new JSONObject().put("source",source).put("key",key).put("graph_hash",hash(graph)),()->{JSONObject session=mirror(source);String id=storeGraph(graph);JSONObject pointer=copy(bound).put("formatVersion",1).put("source",source).put("mirror_id",session.getString("mirror_id")).put("key",key).put("record_id",id);store.put(PREFIX+"mirror_entry:"+session.getString("mirror_id")+":"+hash(key),pointer.toString());return new JSONObject().put("key",key).put("record_id",id).put("record_hash",id).put("local_state","local_saved");});}
    JSONObject completeMirror(String request,String source,JSONArray keys)throws Exception {source(source);return mutate("complete_mirror",request,new JSONObject().put("source",source).put("keys",keys),()->{JSONObject state=state(),session=mirror(source);Set<String> expected=new TreeSet<>();for(int i=0;i<keys.length();i++)if(!expected.add(key(keys.getString(i))))throw fail("DUPLICATE_KEY");JSONArray entries=rows("mirror_entry:"+session.getString("mirror_id")+":");Set<String> actual=new TreeSet<>();for(int i=0;i<entries.length();i++){JSONObject pointer=value(entries.getJSONObject(i));actual.add(pointer.getString("key"));verifyRecord(pointer.getString("record_id"));}if(!actual.equals(expected))throw fail("MIRROR_INCOMPLETE");if(source.equals("active")){if(!state.getString("mode").equals("MIRROR_REQUIRED")||rows("active:").length()!=0)throw fail("ACTIVE_CONFLICT");for(int i=0;i<entries.length();i++){JSONObject pointer=value(entries.getJSONObject(i));store.put(PREFIX+"active:"+hash(pointer.getString("key")),copy(bound).put("formatVersion",1).put("key",pointer.getString("key")).put("record_id",pointer.getString("record_id")).toString());}state.put("mode","ACTIVE").put("mirror_complete",true);}else{if(!state.getString("mode").equals("RESTORE_REVIEW"))throw fail("MIRROR_NOT_ALLOWED");for(int i=0;i<entries.length();i++)candidate(state,source,session.getString("mirror_id"),value(entries.getJSONObject(i)));state.put("device_mirror_complete",true);}session.put("phase","COMPLETE");store.put(PREFIX+"mirror:"+session.getString("mirror_id"),session.toString());saveState(state);return status().put("mirror_id",session.getString("mirror_id")).put("record_count",actual.size()).put("already_complete",false);});}
    private void candidate(JSONObject state,String source,String sourceId,JSONObject pointer)throws Exception {JSONObject value=copy(bound).put("formatVersion",1).put("source",source).put("source_id",sourceId).put("key",pointer.getString("key")).put("record_id",pointer.getString("record_id")).put("archived",false);store.put(PREFIX+"candidate:"+sourceId+":"+hash(pointer.getString("key")+":"+pointer.getString("record_id")),value.toString());}
    private boolean currentCandidate(JSONObject candidate,JSONObject state){return !candidate.optBoolean("archived")&&matches(candidate)&&(candidate.optString("source").equals("backup")&&candidate.optString("source_id").equals(state.optString("backup_source"))||candidate.optString("source").equals("device")&&candidate.optString("source_id").equals(state.optString("device_mirror")));}
    JSONObject reviewCandidates()throws Exception {JSONObject state=state();JSONArray candidates=new JSONArray(),all=rows("candidate:");for(int i=0;i<all.length();i++){JSONObject candidate=value(all.getJSONObject(i));if(!currentCandidate(candidate,state))continue;JSONObject row=record(candidate.getString("record_id"));Object graph=row.get("graph");JSONArray refs=graph instanceof JSONObject?BrowserMediaFiles.references((JSONObject)graph):new JSONArray();long bytes=0;for(int j=0;j<refs.length();j++)bytes=Math.addExact(bytes,refs.getJSONObject(j).getLong("byte_size"));candidates.put(new JSONObject().put("source",candidate.getString("source")).put("key",candidate.getString("key")).put("record_id",candidate.getString("record_id")).put("record_hash",candidate.getString("record_id")).put("blob_count",refs.length()).put("byte_size",bytes).put("label",candidate.getString("key").equals("selected")?"Gespeichertes Bild":"Kundenfoto-Entwurf"));}JSONObject result=copy(bound).put("formatVersion",1).put("required",state.getString("mode").equals("RESTORE_REVIEW")).put("mirror_complete",complete(state)).put("candidates",candidates);return result.put("record_hash",hash(new JSONObject().put("state",state).put("candidates",candidates)));}
    JSONObject prepareRestoreSelection(String request,String expected,JSONArray selected)throws Exception {return mutate("prepare_selection",request,new JSONObject().put("expected",expected).put("selected",selected),()->{JSONObject state=state(),review=reviewCandidates();if(!state.getString("mode").equals("RESTORE_REVIEW")||!complete(state))throw fail("RESTORE_MIRROR_REQUIRED");if(expected==null||!expected.equals(review.getString("record_hash")))throw fail("WRITE_CONFLICT");Set<String> keys=new TreeSet<>();JSONArray chosen=new JSONArray();for(int i=0;i<selected.length();i++){JSONObject item=selected.getJSONObject(i);String key=key(item.getString("key"));if(!keys.add(key))throw fail("DUPLICATE_KEY");JSONObject found=null;JSONArray options=review.getJSONArray("candidates");for(int j=0;j<options.length();j++){JSONObject candidate=options.getJSONObject(j);if(key.equals(candidate.getString("key"))&&item.optString("source").equals(candidate.getString("source"))&&item.optString("record_id").equals(candidate.getString("record_id")))found=candidate;}if(found==null||item.has("record_hash")&&!item.optString("record_hash").equals(found.getString("record_hash")))throw fail("SELECTION_INVALID");verifyRecord(found.getString("record_id"));chosen.put(new JSONObject().put("source",found.getString("source")).put("key",key).put("record_id",found.getString("record_id")));}JSONObject selection=copy(bound).put("formatVersion",1).put("review_hash",expected).put("selected",chosen).put("request_id",request);String selectionHash=hash(selection);store.put(PREFIX+"selection:"+selectionHash,selection.toString());return new JSONObject().put("selection_hash",selectionHash).put("selected_count",chosen.length());});}
    JSONObject activateSelection(String request,String selectionHash)throws Exception {return mutate("activate_selection",request,new JSONObject().put("selection_hash",selectionHash),()->{JSONObject state=state();if(selectionHash==null||!selectionHash.matches("[0-9a-f]{64}"))throw fail("SELECTION_INVALID");if(state.getString("mode").equals("ACTIVE")&&selectionHash.equals(state.optString("activation_selection")))return status().put("already_active",true);String raw=store.get(PREFIX+"selection:"+selectionHash,"");if(raw.isEmpty())throw fail("SELECTION_REQUIRED");JSONObject selection=new JSONObject(raw);version(selection);if(!matches(selection)||!hash(selection).equals(selectionHash)||!state.getString("mode").equals("RESTORE_REVIEW")||!complete(state)||!selection.getString("review_hash").equals(reviewCandidates().getString("record_hash")))throw fail("WRITE_CONFLICT");if(rows("active:").length()!=0)throw fail("ACTIVE_CONFLICT");JSONArray chosen=selection.getJSONArray("selected"),active=new JSONArray();for(int i=0;i<chosen.length();i++){JSONObject item=chosen.getJSONObject(i);verifyRecord(item.getString("record_id"));store.put(PREFIX+"active:"+hash(item.getString("key")),copy(bound).put("formatVersion",1).put("key",item.getString("key")).put("record_id",item.getString("record_id")).toString());active.put(item.getString("key"));}JSONArray candidates=rows("candidate:");for(int i=0;i<candidates.length();i++){JSONObject entry=candidates.getJSONObject(i),candidate=value(entry);if(currentCandidate(candidate,state))store.put(entry.getString("key"),candidate.put("archived",true).put("selection_hash",selectionHash).toString());}state.put("mode","ACTIVE").put("mirror_complete",true).put("activation_selection",selectionHash);saveState(state);return status().put("active_keys",active).put("already_active",false);});}
    JSONObject verifyPreparedRestoreSelection(String request,String expected,JSONArray selected,String selectionHash)throws Exception {request(request);JSONObject state=state();if(selectionHash==null||!selectionHash.matches("[0-9a-f]{64}"))throw fail("SELECTION_INVALID");String raw=store.get(PREFIX+"selection:"+selectionHash,"");if(raw.isEmpty())throw fail("SELECTION_REQUIRED");JSONObject selection=new JSONObject(raw);version(selection);if(!matches(selection)||!hash(selection).equals(selectionHash)||!request.equals(selection.optString("request_id"))||!Objects.equals(expected,selection.optString("review_hash")))throw fail("WRITE_CONFLICT");JSONArray normalized=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<selected.length();i++){JSONObject item=selected.getJSONObject(i);String key=key(item.getString("key")),id=item.getString("record_id");if(!seen.add(key)||item.has("record_hash")&&!id.equals(item.optString("record_hash")))throw fail("SELECTION_INVALID");normalized.put(new JSONObject().put("source",item.getString("source")).put("key",key).put("record_id",id));verifyRecord(id);}if(!hash(normalized).equals(hash(selection.getJSONArray("selected"))))throw fail("WRITE_CONFLICT");if(state.optString("mode").equals("RESTORE_REVIEW")){if(!complete(state)||!Objects.equals(expected,reviewCandidates().getString("record_hash")))throw fail("WRITE_CONFLICT");}else if(state.optString("mode").equals("ACTIVE")&&selectionHash.equals(state.optString("activation_selection"))){JSONArray active=rows("active:");if(active.length()!=normalized.length())throw fail("WRITE_CONFLICT");for(int i=0;i<normalized.length();i++){JSONObject item=normalized.getJSONObject(i),pointer=pointer(item.getString("key"));if(pointer==null||!item.getString("record_id").equals(pointer.optString("record_id")))throw fail("WRITE_CONFLICT");}}else throw fail("WRITE_CONFLICT");return new JSONObject().put("valid",true).put("selection_hash",selectionHash).put("selected_count",normalized.length());}
    void assertReadableReference(String recordId,JSONObject ref)throws Exception {JSONObject state=state();if(!state.getString("mode").equals("ACTIVE")||!complete(state))throw fail("RESTORE_REVIEW_REQUIRED");BrowserMediaFiles.validateReference(ref);boolean active=false;JSONArray pointers=rows("active:");for(int i=0;i<pointers.length();i++){JSONObject pointer=value(pointers.getJSONObject(i));if(matches(pointer)&&recordId.equals(pointer.optString("record_id")))active=true;}if(!active)throw fail("REFERENCE_NOT_ACTIVE");Object graph=record(recordId).get("graph");JSONArray refs=graph instanceof JSONObject?BrowserMediaFiles.references((JSONObject)graph):new JSONArray();for(int i=0;i<refs.length();i++)if(hash(ref).equals(hash(refs.getJSONObject(i))))return;throw fail("REFERENCE_NOT_ACTIVE");}
    void installRestored(String request)throws Exception {request(request);store.transaction(()->{context();String source=hash(new JSONObject().put("request",request).put("context",bound));String raw=store.get(PREFIX+"state","");if(!raw.isEmpty()){JSONObject prior=new JSONObject(raw);version(prior);if(matches(prior)&&request.equals(prior.optString("restore_request")))return prior;}JSONObject state=fresh().put("mode","RESTORE_REVIEW").put("restore_request",request).put("backup_source",source);JSONArray active=rows("active:"),candidates=rows("candidate:");for(int i=0;i<active.length();i++){JSONObject entry=active.getJSONObject(i),pointer=value(entry);record(pointer.getString("record_id"));candidate(state,"backup",source,pointer);store.remove(entry.getString("key"));}for(int i=0;i<candidates.length();i++){JSONObject entry=candidates.getJSONObject(i),pointer=value(entry);if(!pointer.optBoolean("archived")){record(pointer.getString("record_id"));candidate(state,"backup",source,pointer);store.put(entry.getString("key"),pointer.put("archived",true).put("carried_to",source).toString());}}saveState(state);return state;});}
    private void completionProof(JSONObject state)throws Exception {String id=state.optString("mode").equals("ACTIVE")?state.optString("active_mirror"):state.optString("device_mirror");if(state.optString("mode").equals("ACTIVE")&&!state.optString("activation_selection").isEmpty()){String raw=store.get(PREFIX+"selection:"+state.getString("activation_selection"),"");if(raw.isEmpty())throw fail("SELECTION_REQUIRED");JSONObject selection=new JSONObject(raw);version(selection);if(!matches(selection)||!hash(selection).equals(state.getString("activation_selection")))throw fail("SELECTION_INVALID");JSONArray selected=selection.getJSONArray("selected");for(int i=0;i<selected.length();i++)record(selected.getJSONObject(i).getString("record_id"));return;}String raw=store.get(PREFIX+"mirror:"+id,"");if(id.isEmpty()||raw.isEmpty())throw fail("MIRROR_REQUIRED");JSONObject session=new JSONObject(raw);version(session);if(!matches(session)||!session.optString("phase").equals("COMPLETE")||!session.optString("source").equals(state.optString("mode").equals("ACTIVE")?"active":"device"))throw fail("MIRROR_REQUIRED");}
    JSONObject inspectCaptured()throws Exception {JSONObject state=state();if(!complete(state))throw fail("MIRROR_REQUIRED");completionProof(state);JSONArray records=rows("record:");Map<String,JSONObject> unique=new TreeMap<>();Set<String> recordIds=new TreeSet<>();long references=0,bytes=0;for(int i=0;i<records.length();i++){JSONObject entry=records.getJSONObject(i),row=value(entry);String id=row.getString("record_id");if(!entry.getString("key").equals(PREFIX+"record:"+id)||!recordIds.add(id))throw fail("RECORD_INVALID");Object graph=record(id).get("graph");JSONArray refs=graph instanceof JSONObject?BrowserMediaFiles.references((JSONObject)graph):new JSONArray();references+=refs.length();for(int j=0;j<refs.length();j++){JSONObject ref=refs.getJSONObject(j);BrowserMediaFiles.verifyReference(media,ref);JSONObject old=unique.put(ref.getString("sha256"),ref);if(old!=null&&old.getLong("byte_size")!=ref.getLong("byte_size"))throw fail("REFERENCE_INVALID");}}for(JSONObject ref:unique.values())bytes=Math.addExact(bytes,ref.getLong("byte_size"));JSONArray entries=rows("");for(int i=0;i<entries.length();i++){JSONObject entry=entries.getJSONObject(i),row=value(entry);String key=entry.getString("key");if(!(key.equals(PREFIX+"state")||Arrays.asList("record:","active:","history:","request:","mirror:","mirror_entry:","candidate:","selection:").stream().anyMatch(part->key.startsWith(PREFIX+part))))throw fail("VERSION_UNSUPPORTED");if(key.startsWith(PREFIX+"active:")){if(!state.optString("mode").equals("ACTIVE")||!matches(row)||!key.equals(PREFIX+"active:"+hash(key(row.getString("key")))))throw fail("CONTEXT_CHANGED");}if(key.startsWith(PREFIX+"mirror:")&&row.optString("phase").equals("OPEN")&&matches(row))throw fail("MIRROR_REQUIRED");if(key.startsWith(PREFIX+"active:")||key.startsWith(PREFIX+"candidate:")||key.startsWith(PREFIX+"mirror_entry:")||key.startsWith(PREFIX+"history:")){key(row.getString("key"));record(row.getString("record_id"));if(row.has("before")&&!row.isNull("before"))record(row.getString("before"));}if(key.startsWith(PREFIX+"selection:")){JSONArray selected=row.getJSONArray("selected");for(int j=0;j<selected.length();j++)record(selected.getJSONObject(j).getString("record_id"));}}return new JSONObject().put("formatVersion",1).put("mode",state.getString("mode")).put("mirror_complete",true).put("record_count",records.length()).put("reference_count",references).put("blob_count",unique.size()).put("byte_size",bytes).put("record_hash",hash(new JSONArray(recordIds)));}
}
